  // ---- janelas
  "dlg.ok": ["Entendi", "Got it", "Entendido"],
  "dlg.cancel": ["Cancelar", "Cancel", "Cancelar"],
  "dlg.failT": ["A operação não terminou", "The operation didn't finish", "La operación no terminó"],
  "dlg.failD": ["Se os analógicos ficarem estranhos, use <b>Reiniciar o controle</b> em Calibração ou desligue e ligue o cabo: o que não foi salvo some.", "If the sticks feel wrong, use <b>Restart controller</b> in Calibration or replug the cable: anything unsaved is discarded.", "Si los sticks quedan raros, usa <b>Reiniciar el control</b> en Calibración o reconecta el cable: lo que no se guardó se pierde."],
  "dlg.lostT": ["Controle desconectado", "Controller disconnected", "Control desconectado"],
  "dlg.lostD": ["O controle saiu no meio da operação. Ligue o cabo de novo e confira os analógicos; se algo ficou estranho, reinicie o controle.", "The controller dropped mid-operation. Plug it back in and check the sticks; if something's off, restart the controller.", "El control se desconectó en medio de la operación. Conéctalo de nuevo y revisa los sticks; si algo está raro, reinicia el control."],
  "c.title": ["Calibrar o centro", "Calibrate center", "Calibrar el centro"],
  "c.one": ["o analógico", "the stick", "el stick"],
  "c.both": ["os dois analógicos", "both sticks", "los dos sticks"],
  "c.introQuick": ["Deixe {s} <b>soltos</b> e coloque o controle parado na mesa. O controle mede o ponto de descanso sozinho em poucos segundos.", "Leave {s} <b>untouched</b> and set the controller still on a table. It measures the resting point by itself in a few seconds.", "Deja {s} <b>sueltos</b> y pon el control quieto sobre la mesa. Mide el punto de reposo solo en pocos segundos."],
  "c.intro4": ["São 4 passos. Em cada um você empurra {s} para um canto, solta e toca em <b>Continuar</b>.", "There are 4 steps. In each, push {s} to a corner, release and tap <b>Continue</b>.", "Son 4 pasos. En cada uno empujas {s} a una esquina, sueltas y tocas <b>Continuar</b>."],
  "c.dontClose": ["Depois de começar, não feche a página nem tire o cabo até terminar.", "Once started, don't close the page or unplug the cable until it's done.", "Una vez iniciado, no cierres la página ni desconectes el cable hasta terminar."],
  "c.start": ["Começar", "Start", "Empezar"],
  "c.running": ["Calibrando o centro…", "Calibrating center…", "Calibrando el centro…"],
  "c.noTouch": ["Não toque nos analógicos.", "Don't touch the sticks.", "No toques los sticks."],
  "c.step": ["Passo {n} de 4", "Step {n} of 4", "Paso {n} de 4"],
  "c.tl": ["canto de cima, à esquerda", "top-left corner", "esquina superior izquierda"],
