  "c.pushOne": ["Empurre o analógico até o <b>{c}</b> e solte. Quando ele voltar ao centro, toque em Continuar.", "Push the stick to the <b>{c}</b> and release. When it returns to center, tap Continue.", "Empuja el stick hasta la <b>{c}</b> y suéltalo. Cuando vuelva al centro, toca Continuar."],
  "c.pushBoth": ["Empurre os dois analógicos até o <b>{c}</b> e solte. Quando eles voltarem ao centro, toque em Continuar.", "Push both sticks to the <b>{c}</b> and release. When they return to center, tap Continue.", "Empuja los dos sticks hasta la <b>{c}</b> y suéltalos. Cuando vuelvan al centro, toca Continuar."],
  "c.next": ["Continuar", "Continue", "Continuar"],
  "c.reading": ["Lendo…", "Reading…", "Leyendo…"],
  "c.doneT": ["Centro calibrado", "Center calibrated", "Centro calibrado"],
  "c.doneD": ["Teste os analógicos em <b>Analógicos</b> (modo Zoom 10x). Ficou bom? Toque em <b>Salvar no controle</b>. Não gostou? <b>Reiniciar o controle</b> desfaz.", "Test the sticks in <b>Sticks</b> (Zoom 10x mode). Good? Tap <b>Save to controller</b>. Not happy? <b>Restart controller</b> undoes it.", "Prueba los sticks en <b>Sticks</b> (modo Zoom 10x). ¿Quedó bien? Toca <b>Guardar en el control</b>. ¿No? <b>Reiniciar el control</b> lo deshace."],
  "r.title": ["Calibrar o alcance", "Calibrate range", "Calibrar el rango"],
  "r.intro": ["Gire {s} <b>devagar, encostando na borda</b>: pelo menos 2 voltas para um lado e 2 para o outro.", "Rotate {s} <b>slowly, touching the edge</b>: at least 2 turns one way and 2 the other.", "Gira {s} <b>despacio, tocando el borde</b>: al menos 2 vueltas hacia un lado y 2 hacia el otro."],
  "r.warn": ["Se tocar em Concluir sem girar, a calibração fica incompleta e você precisa repetir.", "If you tap Finish without rotating, calibration will be incomplete and you'll need to repeat it.", "Si tocas Terminar sin girar, la calibración queda incompleta y tendrás que repetirla."],
  "r.spin": ["Gire os analógicos", "Rotate the sticks", "Gira los sticks"],
  "r.keep": ["O controle está medindo. Continue girando mesmo se a barra parar.", "The controller is measuring. Keep rotating even if the bar stops.", "El control está midiendo. Sigue girando aunque la barra se detenga."],
  "r.done": ["Concluir", "Finish", "Terminar"],
  "r.turns": ["voltas: esquerdo {l}/{n} · direito {r}/{n}", "turns: left {l}/{n} · right {r}/{n}", "vueltas: izquierdo {l}/{n} · derecho {r}/{n}"],
  "r.turnsOne": ["voltas: {l}/{n}", "turns: {l}/{n}", "vueltas: {l}/{n}"],
  "r.saving": ["Gravando…", "Saving…", "Guardando…"],
  "r.doneT": ["Alcance calibrado", "Range calibrated", "Rango calibrado"],
  "r.doneD": ["Em <b>Analógicos</b>, use o modo Circularidade e veja se o círculo ficou redondo. Ficou bom? Toque em <b>Salvar no controle</b>.", "In <b>Sticks</b>, use Circularity mode and check the circle is round. Good? Tap <b>Save to controller</b>.", "En <b>Sticks</b>, usa el modo Circularidad y mira si el círculo quedó redondo. ¿Bien? Toca <b>Guardar en el control</b>."],
  "s.title": ["Salvar no controle", "Save to controller", "Guardar en el control"],
  "s.intro": ["A calibração atual fica <b>gravada de vez</b> no controle e continua depois de desligar.", "The current calibration will be <b>stored permanently</b> and kept after power-off.", "La calibración actual queda <b>grabada para siempre</b> en el control y se mantiene al apagarlo."],
  "s.edge": ["No DualSense Edge a gravação vai para os módulos dos analógicos. Não tire o cabo até terminar.", "On DualSense Edge it's written to the stick modules. Don't unplug until it's done.", "En el DualSense Edge se graba en los módulos de los sticks. No desconectes hasta terminar."],
  "s.btn": ["Salvar", "Save", "Guardar"],
  "s.running": ["Salvando…", "Saving…", "Guardando…"],
  "s.noCable": ["Não tire o cabo.", "Don't unplug the cable.", "No desconectes el cable."],
  "s.doneT": ["Salvo", "Saved", "Guardado"],
  "s.doneD": ["A calibração ficou gravada no controle.", "The calibration is stored in the controller.", "La calibración quedó grabada en el control."],
  "s.doneEdge": ["Se ela não continuar depois de reiniciar, confira as soldas dos módulos.", "If it's not kept after restarting, check the module solder joints.", "Si no se mantiene al reiniciar, revisa las soldaduras de los módulos."],
  "u.title": ["Desfazer a calibração", "Undo calibration", "Deshacer la calibración"],
  "u.d": ["O controle vai <b>reiniciar</b> e voltar para a última calibração salva. Ele desconecta e conecta de novo sozinho.", "The controller will <b>restart</b> and go back to the last saved calibration. It disconnects and reconnects by itself.", "El control se <b>reiniciará</b> y volverá a la última calibración guardada. Se desconecta y vuelve a conectarse solo."],
  "u.btn": ["Reiniciar o controle", "Restart controller", "Reiniciar el control"],

